"169 :   CanInlineResult canInlineReferenceToFunction(NodeTraversal t,
170 :       Node callNode, Node fnNode, Set<String> needAliases,
171 :       InliningMode mode, boolean referencesThis, boolean containsFunctions) {
172 :     // TODO(johnlenz): This function takes too many parameter, without
173 :     // context.  Modify the API to take a structure describing the function.
174 : 
175 :     // Allow direct function calls or "fn.call" style calls.
176 :     if (!isSupportedCallType(callNode)) {
177 :       return CanInlineResult.NO;
178 :     }
179 : 
180 :     // Limit where functions that contain functions can be inline.  Introducing
181 :     // an inner function into another function can capture a variable and cause
182 :     // a memory leak.  This isn't a problem in the global scope as those values
183 :     // last until explicitly cleared.
184 :     if (containsFunctions) {
185 :       if (!assumeMinimumCapture && !t.inGlobalScope()) {
186 :         // TODO(johnlenz): Allow inlining into any scope without local names or
187 :         // inner functions.
188 :         return CanInlineResult.NO;
189 :       } else if (NodeUtil.isWithinLoop(callNode)) {
190 :         // An inner closure maybe relying on a local value holding a value for a
191 :         // single iteration through a loop.
192 :         return CanInlineResult.NO;
193 :       }
194 :     }
195 : 
196 :     // TODO(johnlenz): Add support for 'apply'
197 :     if (referencesThis && !NodeUtil.isFunctionObjectCall(callNode)) {
198 :       // TODO(johnlenz): Allow 'this' references to be replaced with a
199 :       // global 'this' object.
200 :       return CanInlineResult.NO;
201 :     }
202 : 
203 :     if (mode == InliningMode.DIRECT) {
204 :       return canInlineReferenceDirectly(callNode, fnNode);
205 :     } else {
206 :       return canInlineReferenceAsStatementBlock(
207 :           t, callNode, fnNode, needAliases);
208 :     }
209 :   }"

"658 :   private CanInlineResult canInlineReferenceDirectly(
659 :       Node callNode, Node fnNode) {
660 :     if (!isDirectCallNodeReplacementPossible(fnNode)) {
661 :       return CanInlineResult.NO;
662 :     }
663 : 
664 :     Node block = fnNode.getLastChild();
665 : 
666 :     // CALL NODE: [ NAME, ARG1, ARG2, ... ]
667 :     Node cArg = callNode.getFirstChild().getNext();
668 : 
669 :     // Functions called via 'call' and 'apply' have a this-object as
670 :     // the first parameter, but this is not part of the called function's
671 :     // parameter list.
672 :     if (callNode.getFirstChild().getType() != Token.NAME) {
673 :       if (NodeUtil.isFunctionObjectCall(callNode)) {
674 :         // TODO(johnlenz): Support replace this with a value.
675 :         if (cArg == null || cArg.getType() != Token.THIS) {
676 :           return CanInlineResult.NO;
677 :         }
678 :         cArg = cArg.getNext();
679 :       } else {
680 :         // ".apply" call should be filtered before this.
681 :         Preconditions.checkState(!NodeUtil.isFunctionObjectApply(callNode));
682 :       }
683 :     }
684 : 
685 :     // FUNCTION NODE -> LP NODE: [ ARG1, ARG2, ... ]
686 :     Node fnParam = NodeUtil.getFunctionParameters(fnNode).getFirstChild();
687 :     while (cArg != null || fnParam != null) {
688 :       // For each named parameter check if a mutable argument use more than one.
689 :       if (fnParam != null) {
690 :         if (cArg != null) {
691 :           // Check for arguments that are evaluated more than once.
692 :           // Note: Unlike block inlining, there it is not possible that a
693 :           // parameter reference will be in a loop.
694 :           if (NodeUtil.mayEffectMutableState(cArg)
695 :               && NodeUtil.getNameReferenceCount(
696 :                   block, fnParam.getString()) > 1) {
697 :             return CanInlineResult.NO;
698 :           }
699 :         }
700 : 
701 :         // Move to the next name.
702 :         fnParam = fnParam.getNext();
703 :       }
704 : 
705 :       // For every call argument check for side-effects, even if there
706 :       // isn't a named parameter to match.
707 :       if (cArg != null) {
708 :         if (NodeUtil.mayHaveSideEffects(cArg)) {
709 :           return CanInlineResult.NO;
710 :         }
711 :         cArg = cArg.getNext();
712 :       }
713 :     }
714 : 
715 :     return CanInlineResult.YES;
716 :   }"

"550 :   private CanInlineResult canInlineReferenceAsStatementBlock(
551 :       NodeTraversal t, Node callNode, Node fnNode, Set<String> namesToAlias) {
552 :     CallSiteType callSiteType = classifyCallSite(callNode);
553 :     if (callSiteType == CallSiteType.UNSUPPORTED) {
554 :       return CanInlineResult.NO;
555 :     }
556 : 
557 :     if (!allowDecomposition
558 :         && callSiteType == CallSiteType.DECOMPOSABLE_EXPRESSION) {
559 :       return CanInlineResult.NO;
560 :     }
561 : 
562 :     if (!callMeetsBlockInliningRequirements(
563 :             t, callNode, fnNode, namesToAlias)) {
564 :       return CanInlineResult.NO;
565 :     }
566 : 
567 :     if (callSiteType == CallSiteType.DECOMPOSABLE_EXPRESSION)  {
568 :       return CanInlineResult.AFTER_DECOMPOSITION;
569 :     } else {
570 :       return CanInlineResult.YES;
571 :     }
572 :   }"

"351 :   private CallSiteType classifyCallSite(Node callNode) {
352 :     Node parent = callNode.getParent();
353 :     Node grandParent = parent.getParent();
354 : 
355 :     // Verify the call site:
356 :     if (NodeUtil.isExprCall(parent)) {
357 :       // This is a simple call?  Example: "foo();".
358 :       return CallSiteType.SIMPLE_CALL;
359 :     } else if (NodeUtil.isExprAssign(grandParent)
360 :         && !NodeUtil.isVarOrSimpleAssignLhs(callNode, parent)
361 :         && parent.getFirstChild().getType() == Token.NAME
362 :         && !NodeUtil.isConstantName(parent.getFirstChild())) {
363 :       // This is a simple assignment.  Example: "x = foo();"
364 :       return CallSiteType.SIMPLE_ASSIGNMENT;
365 :     } else if (parent.getType() == Token.NAME
366 :         && !NodeUtil.isConstantName(parent)
367 :         && grandParent.getType() == Token.VAR
368 :         && grandParent.hasOneChild()) {
369 :       // This is a var declaration.  Example: "var x = foo();"
370 :       // TODO(johnlenz): Should we be checking for constants on the
371 :       // left-hand-side of the assignments (and handling them as EXPRESSION?
372 :       return CallSiteType.VAR_DECL_SIMPLE_ASSIGNMENT;
373 :     } else {
374 :       Node expressionRoot = ExpressionDecomposer.findExpressionRoot(callNode);
375 :       if (expressionRoot != null) {
376 :         ExpressionDecomposer decomposer = new ExpressionDecomposer(
377 :             compiler, safeNameIdSupplier, knownConstants);
378 :         DecompositionType type = decomposer.canExposeExpression(
379 :             callNode);
380 :         if (type == DecompositionType.MOVABLE) {
381 :           return CallSiteType.EXPRESSION;
382 :         } else if (type == DecompositionType.DECOMPOSABLE) {
383 :           return CallSiteType.DECOMPOSABLE_EXPRESSION;
384 :         } else {
385 :           Preconditions.checkState(type == DecompositionType.UNDECOMPOSABLE);
386 :         }
387 :       }
388 :     }
389 : 
390 :     return CallSiteType.UNSUPPORTED;
391 :   }"

